#!/usr/bin/env python3
"""Public examples only. Run inside the candidate's public workspace."""
import json
import math
import pathlib
import subprocess
import sys
import tempfile


def unique(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def equal(expected, actual):
    if type(expected) is dict:
        return (type(actual) is dict and expected.keys() == actual.keys()
                and all(equal(v, actual[k]) for k, v in expected.items()))
    if type(expected) is list:
        return (type(actual) is list and len(expected) == len(actual)
                and all(equal(a, b) for a, b in zip(expected, actual)))
    if type(expected) is float:
        return type(actual) in (int, float) and math.isfinite(actual) and abs(expected - actual) <= 1e-8
    return type(expected) is type(actual) and expected == actual


def main():
    root = pathlib.Path(__file__).resolve().parent
    failures = 0
    for source in sorted((root / 'examples').glob('*.input.json')):
        expected = json.loads(source.with_name(source.name.replace('.input.', '.expected.')).read_text())
        try:
            # File-backed capture keeps the checker's own memory bounded.
            with tempfile.TemporaryFile() as stdout, tempfile.TemporaryFile() as stderr:
                result = subprocess.run([sys.executable, '-I', str(root / 'submission/main.py')],
                                        input=source.read_bytes(), stdout=stdout, stderr=stderr,
                                        cwd=root, timeout=90)
                stdout.seek(0)
                raw = stdout.read(16777217)
                if len(raw) > 16777216:
                    raise ValueError('output too large')
                actual = json.loads(raw, object_pairs_hook=unique,
                                    parse_constant=lambda x: (_ for _ in ()).throw(ValueError(x)))
                passed = result.returncode == 0 and equal(expected, actual)
        except (ValueError, OSError, subprocess.TimeoutExpired):
            passed = False
        print(('PASS ' if passed else 'FAIL ') + source.name)
        failures += int(not passed)
    print('Public examples only; additional networks are evaluated separately.')
    return int(failures > 0)


if __name__ == '__main__':
    raise SystemExit(main())

#!/usr/bin/env python3
"""Prior-only baseline: path cleanup and scoring, without joint inference.

This deliberately treats every observed link as removed in round one.
It is useful on one-link RIBs, but core topology and probabilities need work.
"""
import json
import sys
from fractions import Fraction


def clean(path, ixps):
    result = []
    for asn in path:
        if asn not in ixps and (not result or result[-1] != asn):
            result.append(asn)
    return result


def canonical(a, b):
    return min(a, b), max(a, b)


def baseline(data):
    ixps = set(data['ixps'])
    uniform = (Fraction(1, 3),) * 3
    priors, declared = {}, {}
    for record in data['priors']:
        a, b = record['link']
        weights = record['weights']
        p = tuple(Fraction(v, sum(weights)) for v in weights)
        priors[canonical(a, b)] = p if a < b else p[::-1]
    for record in data['declared']:
        a, b = record['link']
        p = tuple(Fraction(int(record['rel'] == rel)) for rel in ('c2p', 'p2p', 'p2c'))
        declared[canonical(a, b)] = p if a < b else p[::-1]
    seen = set()
    for record in data['rib']:
        p = clean(record['path'], ixps)
        if len(set(p)) == len(p):
            seen.update(canonical(a, b) for a, b in zip(p, p[1:]))
    links = [dict(link=list(e), round=1, prob=list(map(float, priors.get(e, uniform))))
             for e in sorted(seen)]
    queries = []
    for record in data['queries']:
        p = clean(record['path'], ixps)
        answer = dict(id=record['id'], path=p, status='ok', score=None,
                      full=None, witness=None, leaked=None)
        if len(set(p)) != len(p):
            answer['status'] = 'loop'
        else:
            probabilities = []
            for a, b in zip(p, p[1:]):
                e = canonical(a, b)
                v = declared.get(e, priors.get(e, uniform))
                probabilities.append(v if a < b else v[::-1])
            triples = [x[0] + y[2] - x[0] * y[2]
                       for x, y in zip(probabilities, probabilities[1:])]
            score = min(triples) if triples else Fraction(1)
            up, peer, down = Fraction(1), Fraction(0), Fraction(0)
            for a, b, c in probabilities:
                up, peer, down = up * a, up * b, (up + peer + down) * c
            answer.update(score=float(score), full=float(up + peer + down),
                          witness=triples.index(score) if triples else None,
                          leaked=score < Fraction(*record['threshold']))
        queries.append(answer)
    return dict(version=1, links=links, queries=queries)


if __name__ == '__main__':
    try:
        answer = baseline(json.load(sys.stdin))
    except (ValueError, TypeError, KeyError, IndexError, ZeroDivisionError):
        answer = {'error': 'invalid'}
    print(json.dumps(answer, allow_nan=False))

