        for k in range(n):  # c2p* p2p p2c*, p2p at position k
            wgt = probs[k][1]
            for i in range(k):
                wgt *= probs[i][0]
            for i in range(k + 1, n):
                wgt *= probs[i][2]
            full += wgt
        out_queries.append({"id": qid, "path": list(qn), "status": "ok",
                            "score": float(score), "full": float(full),
                            "witness": witness,
                            "leaked": score < Fraction(*th)})
    return {"version": 1, "links": out_links, "queries": out_queries}


if __name__ == "__main__":
    raw = sys.stdin.buffer.read()
    try:
        data = json.loads(raw)
        ans = solve(data)
    except Invalid:
        ans = {"error": "invalid"}
    print(json.dumps(ans, allow_nan=False))
