#!/usr/bin/env python3
"""Random differential tester: submission/main.py vs tmp/ref.py."""
import json
import math
import random
import subprocess
import sys
import time

sys.path.insert(0, 'tmp')
import ref as _ref


def equal(expected, actual, tol=1e-9):
    if type(expected) is dict:
        return (type(actual) is dict and expected.keys() == actual.keys()
                and all(equal(v, actual[k], tol) for k, v in expected.items()))
    if type(expected) is list:
        return (type(actual) is list and len(expected) == len(actual)
                and all(equal(a, b, tol) for a, b in zip(expected, actual)))
    if type(expected) is float:
        return type(actual) in (int, float) and math.isfinite(actual) and abs(expected - actual) <= tol
    return type(expected) is type(actual) and expected == actual


def compute_core(doc):
    try:
        ixps, rib, priors, declared, order_pairs, queries = _ref.validate(doc)
        agg = {}
        for p, c in rib:
            q = _ref.norm(p, ixps)
            if len(q) < 2 or len(set(q)) != len(q):
                continue
            t = tuple(q)
            agg[t] = agg.get(t, 0) + c
        final, rounds, links = _ref.peel_ref(agg)
        if len(links) > 4096:
            return None
        core = sorted(k for k in links if k not in rounds)
        if len(core) > 64:
            return None
        return core
    except _ref.Invalid:
        return None


def run(prog, data_bytes):
    r = subprocess.run([sys.executable, '-I', prog], input=data_bytes,
                       capture_output=True, timeout=90)
    if r.returncode != 0:
        return {'__crash__': r.stderr.decode()[:500]}
    return json.loads(r.stdout)


def gen_input(rng):
    n_asn = rng.randint(2, 8)
    asns = list(range(1, n_asn + 1))
    ixps = []
    if rng.random() < 0.3:
        ixps = rng.sample(asns, rng.randint(1, max(1, n_asn // 3)))
    usable = [a for a in asns if a not in ixps]
    rib = []
    nrib = rng.randint(0, 8)
    strat = rng.random()
    if strat < 0.4 and len(usable) >= 3:
        base = usable[:]
        rng.shuffle(base)
        base = base[:rng.randint(3, len(base))]
        n = len(base)
        for _ in range(rng.randint(1, n)):
            k = rng.randrange(n)
            p = base[k:] + base[:k]
            if rng.random() < 0.5:
                p = p[::-1]
            rib.append({'path': p, 'count': rng.randint(1, 3)})
    elif strat < 0.6:
        for _ in range(rng.randint(1, 3)):
            p = usable[:] if rng.random() < 0.5 else asns[:]
            rng.shuffle(p)
            if rng.random() < 0.5:
                p = p[::-1]
            rib.append({'path': p, 'count': rng.randint(1, 3)})
    for _ in range(nrib):
        L = rng.randint(0, 6)
        p = []
        for _ in range(L):
            if p and rng.random() < 0.15:
                p.append(p[-1])
            else:
                p.append(rng.choice(asns))
        if ixps and p and rng.random() < 0.15:
            p.insert(rng.randint(0, len(p)), rng.choice(ixps))
        rib.append({'path': p, 'count': rng.randint(1, 5)})
    priors = []
    seen = set()
    for _ in range(rng.randint(0, 5)):
        u, v = rng.sample(asns, 2)
        key = (min(u, v), max(u, v))
        if key in seen:
            continue
        seen.add(key)
        w = [rng.randint(0, 3) for _ in range(3)]
        if sum(w) == 0:
            w[rng.randrange(3)] = 1
        priors.append({'link': [u, v], 'weights': w})
    declared = []
    dseen = set()
    for _ in range(rng.randint(0, 3)):
        u, v = rng.sample(asns, 2)
        key = (min(u, v), max(u, v))
        if key in dseen:
            continue
        dseen.add(key)
        declared.append({'link': [u, v], 'rel': rng.choice(['c2p', 'p2p', 'p2c'])})
    queries = []
    for i in range(rng.randint(0, 6)):
        L = rng.randint(0, 5)
        p = [rng.choice(asns) for _ in range(L)]
        a = rng.randint(0, 10)
        b = rng.randint(max(a, 1), 10)
        queries.append({'id': 'q%d' % i, 'path': p, 'threshold': [a, b]})
    return {'version': 1, 'ixps': ixps, 'rib': rib, 'priors': priors,
            'declared': declared, 'order': [], 'queries': queries}


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    rng = random.Random(seed)
    t0 = time.time()
    fails = 0
    outcomes = {}
    for it in range(count):
        doc = gen_input(rng)
        core = compute_core(doc)
        if core is not None:
            order = [list(c) for c in core]
            rng.shuffle(order)
            doc['order'] = order
        raw = json.dumps(doc).encode()
        ref = run('tmp/ref.py', raw)
        if '__crash__' in ref:
            print('REF CRASH at', it)
            print(ref['__crash__'])
            open('tmp/fail_%d.json' % it, 'w').write(json.dumps(doc))
            return 1
        out = run('submission/main.py', raw)
        if '__crash__' in out:
            tag = 'crash'
        elif out.get('error') == 'zero-partition':
            tag = 'zeropart'
        elif out.get('error') == 'invalid':
            tag = 'invalid'
        elif any(r['round'] == 0 for r in out.get('links', [])):
            tag = 'core'
        else:
            tag = 'ok'
        outcomes[tag] = outcomes.get(tag, 0) + 1
        if '__crash__' in out:
            fails += 1
            print('CRASH at', it)
            print(out['__crash__'])
            open('tmp/fail_%d.json' % it, 'w').write(json.dumps(doc))
            continue
        if not equal(ref, out):
            fails += 1
            print('MISMATCH at iteration', it)
            print('ref:', json.dumps(ref)[:1500])
            print('got:', json.dumps(out)[:1500])
            open('tmp/fail_%d.json' % it, 'w').write(json.dumps(doc))
            if fails >= 5:
                break
    print('done %d iterations, %d failures, %.1fs' % (count, fails, time.time() - t0))
    print('outcomes:', outcomes)
    return 1 if fails else 0


if __name__ == '__main__':
    raise SystemExit(main())
